                return False
            i += 6
        return True

    fib_sequence = [0, 1]
    index = 2
    prime_fib_numbers = []

    while len(prime_fib_numbers) < n:
        fib_number = fib_sequence[index - 1] + fib_sequence[index - 2]
        fib_sequence.append(fib_number)
        if is_prime(fib_number):
            prime_fib_numbers.append(fib_number)
        index += 1

    return prime_fib_numbers[n - 1]
