def prime_fib(n: int):
    if n < 1:
        return None

    def is_prime(x):
        if x < 2:
            return False
        if x in (2, 3):
            return True
        if x % 2 == 0:
            return False
        for i in range(3, int(x**0.5) + 1, 2):
            if x % i == 0:
                return False
        return True

    fib_nums = [0, 1]
    primes = []

    while len(primes) < n:
        next_fib = fib_nums[-1] + fib_nums[-2]
        if is_prime(next_fib):
            primes.append(next_fib)
        fib_nums.append(next_fib)

    return primes[-1]
